/* Bundle exporter — assembles a downloadable .zip.
 *
 * The "c" target is a build-ready Momentum app folder that unzips straight
 * into Ranzlappen/Flipper's C-Apps/<app>/ and builds with uFBT.
 * The "js" target is a browser canvas PREVIEW (not a deployable Flipper
 * app — the Momentum JS runtime has no pixel-canvas API).
 *
 * Pure: all environment bits (JSZip, the loaded exporters, PNG renderers,
 * the lib source files) are injected by the caller.
 *
 *   const { blob, filename } = await exportBundle(state, {
 *     target, exporters, JSZip, renderIconPng, renderAppIconPng,
 *     renderIconPng1, libFiles });
 */

import { appMeta } from "./fam.js";

function ns(state) {
  return (state.app.namespace || "app").replace(/[^a-zA-Z0-9_]/g, "_") || "app";
}

function referencedIcons(state) {
  const used = new Set();
  for (const s of state.screens || []) {
    for (const w of s.widgets || []) {
      if (w.type === "icon" && w.iconId) used.add(w.iconId);
    }
  }
  return (state.icons || []).filter((i) => used.has(i.id));
}

function cReadme(m) {
  return `# ${m.name}

Generated by **Flipper GUI Studio** — a build-ready Momentum C app.

## Build

This folder drops straight into the Momentum App Framework
(\`Ranzlappen/Flipper\`) at \`C-Apps/${m.folder}/\`.

\`\`\`sh
pip install --upgrade ufbt
ufbt update --index-url=https://up.momentum-fw.dev/firmware/directory.json --channel=release
cd C-Apps/${m.folder}
ufbt                 # builds dist/${m.appid}.fap
ufbt launch          # build + upload + run over USB
\`\`\`

Deploy the \`.fap\` to \`/ext/apps/${m.category}/${m.appid}.fap\` on your Flipper.

Before opening a PR, validate from the repo's \`JS-Apps/\` directory:

\`\`\`sh
npm run validate
\`\`\`

## Files

- \`${m.appid}.flipper-gui.json\` — the design spec and **source of truth**.
  Load it back into Flipper GUI Studio to keep editing. Everything below
  except \`${m.appid}.c\` regenerates from it.
- \`application.fam\` — manifest (appid \`${m.appid}\`, entry \`${m.entry}\`).
  Generated from the JSON — don't hand-edit.
- \`${m.appid}.c\` — entry point, **generated once and now yours**. Override
  \`${m.ns}_on_event()\` here for your logic; re-export never overwrites it.
- \`${m.ns}_scene.c\` / \`${m.ns}_scene.h\` — generated screens, drawing and
  input. Regenerated from the JSON — don't hand-edit.
- \`icon.png\` — 10x10 launcher icon.

## Editing

Don't hand-edit the generated scene. Instead **Load JSON** the
\`${m.appid}.flipper-gui.json\` sidecar back into Flipper GUI Studio, make your
change, and re-export the C bundle over this folder. On re-export you keep your
existing \`${m.appid}.c\` and overwrite only \`application.fam\`,
\`${m.ns}_scene.c\`/\`.h\`, and the JSON sidecar. CI (\`npm run regen-check\`)
regenerates the FAM + scene from the committed JSON and byte-diffs them, so the
spec and the generated files must stay in lockstep.
`;
}

function jsReadme(name) {
  return `# ${name} — browser preview (not deployable)

Generated by Flipper GUI Studio. Renders the 128x64 design to an HTML
canvas, pixel-identical to the editor.

> This is a **preview only**. It does not run on a Flipper Zero — the
> Momentum JS runtime has no pixel-canvas drawing API. To build a real
> app from this design, use the **C app** bundle instead.

## Files

- \`index.html\` — open it (over a static server) to preview every screen.
- \`spec.json\` — the full design (screens, widgets, icons).
- \`render.js\` — \`renderScreen(ctx, screen, icons)\` + \`renderAll(spec, mount)\`.
- \`lib/\` — the shared 1-bit renderer + fonts (do not edit).
- \`icons.js\` — \`name → { w, h, bits, dataURL }\`.
- \`icons/png/\` — each icon as a transparent PNG (1x and @4x).

## Use

\`\`\`sh
python3 -m http.server
\`\`\`
`;
}

const RENDER_JS = `/* Standalone screen renderer for the exported design. Shares the exact
   1-bit drawing code used by Flipper GUI Studio's editor. */

import { drawScene } from "./lib/draw-scene.js";
import { preloadFonts } from "./lib/font-render.js";

const PAPER = "#f0f0d0"; // Flipper LCD background

export function renderScreen(ctx, screen, icons, now) {
  ctx.fillStyle = PAPER;
  ctx.fillRect(0, 0, 128, 64);
  drawScene(ctx, screen.widgets || [], icons || [], now != null ? { now } : {});
}

export async function renderAll(spec, mount) {
  await preloadFonts();
  const frames = [];
  for (const screen of spec.screens || []) {
    const wrap = document.createElement("div");
    wrap.className = "screen";
    const h = document.createElement("h2");
    h.textContent = screen.name || screen.id;
    const cv = document.createElement("canvas");
    cv.width = 128;
    cv.height = 64;
    const c2d = cv.getContext("2d");
    renderScreen(c2d, screen, spec.icons || [], 0);
    wrap.appendChild(h);
    wrap.appendChild(cv);
    mount.appendChild(wrap);
    frames.push({ ctx: c2d, screen });
  }
  // Side-scroll long text, unless the design has none or motion is reduced.
  const anyScroll = (spec.screens || []).some((s) => (s.widgets || []).some((w) => w.scroll));
  const reduce = typeof matchMedia === "function" && matchMedia("(prefers-reduced-motion: reduce)").matches;
  if (!anyScroll || reduce) return;
  const start = performance.now();
  const tick = (t) => {
    for (const f of frames) renderScreen(f.ctx, f.screen, spec.icons || [], t - start);
    requestAnimationFrame(tick);
  };
  requestAnimationFrame(tick);
}
`;

function demoHtml(name) {
  return `<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8" />
<meta name="viewport" content="width=device-width, initial-scale=1" />
<title>${name} — Flipper GUI preview</title>
<style>
  body { margin: 0; padding: 24px; background: #1b1d22; color: #e8e8e8; font-family: system-ui, sans-serif; }
  h1 { font: 600 16px ui-monospace, monospace; }
  .screen { margin-bottom: 24px; }
  .screen h2 { font: 12px ui-monospace, monospace; color: #9aa; margin: 0 0 6px; }
  canvas { image-rendering: pixelated; width: 512px; height: 256px; background: #f0f0d0; display: block; border: 1px solid #333; }
</style>
</head>
<body>
<h1>${name}</h1>
<div id="mount"></div>
<script type="module">
  import { renderAll } from "./render.js";
  const spec = await fetch("./spec.json").then((r) => r.json());
  renderAll(spec, document.getElementById("mount"));
</script>
</body>
</html>
`;
}

export async function exportBundle(state, { target, exporters, JSZip, renderIconPng, renderAppIconPng, renderIconPng1, libFiles }) {
  const zip = new JSZip();

  if (target === "c") {
    const m = appMeta(state);
    const root = zip.folder(m.folder);
    const fam = exporters.fam();
    root.file(fam.filename, fam.text);
    const entry = exporters.entry();
    root.file(entry.filename, entry.text);
    for (const f of exporters.scene()) root.file(f.filename, f.text); // [h, c]
    // The round-trippable design spec — source of truth for the FAM + scene.
    // Ships in the C bundle so the folder is self-describing and re-editable
    // (Load JSON ← this file), and so CI can regenerate-and-diff against it.
    const spec = exporters.json();
    root.file(spec.filename, spec.text);
    root.file("icon.png", await renderAppIconPng(state));
    if (m.iconMode === "assets") {
      const refs = referencedIcons(state);
      if (refs.length) {
        const imgs = root.folder("images");
        for (const ic of refs) {
          // Drop the leading I_ so uFBT's asset compiler regenerates I_<name>.
          const base = ic.name.replace(/^I_/, "");
          imgs.file(`${base}.png`, await renderIconPng1(ic));
        }
      }
    }
    root.file("README.md", cReadme(m));
    return { blob: await zip.generateAsync({ type: "blob" }), filename: `${m.folder}.zip` };
  }

  // JS preview target.
  const name = ns(state);
  const root = zip.folder(`${name}_preview`);
  root.file("spec.json", exporters.json().text);
  root.file("render.js", RENDER_JS);
  root.file("index.html", demoHtml(name));
  root.file("README.md", jsReadme(name));

  for (const [path, text] of Object.entries(libFiles)) {
    root.file(`lib/${path}`, text);
  }

  const png = root.folder("icons/png");
  const iconEntries = [];
  for (const ic of state.icons) {
    const one = await renderIconPng(ic, 1);
    const four = await renderIconPng(ic, 4);
    png.file(`${ic.name}.png`, one.blob);
    png.file(`${ic.name}@4x.png`, four.blob);
    iconEntries.push(
      `  ${JSON.stringify(ic.name)}: { w: ${ic.w}, h: ${ic.h}, ` +
      `bits: ${JSON.stringify(ic.bits)}, dataURL: ${JSON.stringify(one.dataURL)} }`
    );
  }
  root.file("icons.js",
    `/* Icon assets for ${name}. bits = base64 XBM (LSB-first); dataURL = PNG. */\n` +
    `export default {\n${iconEntries.join(",\n")}\n};\n`);

  return { blob: await zip.generateAsync({ type: "blob" }), filename: `${name}_preview.zip` };
}
